import { loadUser } from "./loader.js";

// id -> 真取 promise。缓存 promise（而非已解析的值），
// 这样并发发起的同 id 请求也共用同一次 load。
const cache = new Map();

export async function getUser(id) {
  const hit = cache.get(id);
  if (hit) return hit;

  const pending = loadUser(id);
  cache.set(id, pending);
  try {
    return await pending;
  } catch (err) {
    // 真取失败就别把 rejected promise 留在缓存里，否则该 id 之后永远失败
    cache.delete(id);
    throw err;
  }
}

export function resetCache() {
  cache.clear();
}

