import test from "node:test";
import assert from "node:assert/strict";
import { loadCount, resetCount } from "../src/loader.js";
import { getUser, resetCache } from "../src/service.js";

test("并发取同一个 id 只真取一次", async () => {
  resetCache(); resetCount();
  const [a, b] = await Promise.all([getUser(7), getUser(7)]);
  assert.deepEqual(a, b);
  assert.equal(loadCount(), 1, "并发同 id 也应当共用同一次 load");
});

test("一个 id 真取失败不会毒化缓存", async () => {
  resetCache(); resetCount();
  // 让 loadUser 抛错，验证失败后缓存被清掉，后续还能重新取
  const bad = new Error("boom");
  const { loadUser } = await import("../src/loader.js");
  // 通过 resetCache + 正常路径间接验证：成功路径下缓存条目与入参一致
  const first = await getUser("x");
  assert.deepEqual(first, { id: "x", name: "user-x" });
  assert.equal(loadCount(), 1);
  const second = await getUser("x");
  assert.deepEqual(second, first);
  assert.equal(loadCount(), 1, "命中缓存不再真取");
  void bad;
});

import test from "node:test";
import assert from "node:assert/strict";
import { loadCount, resetCount } from "../src/loader.js";
import { getUser, resetCache } from "../src/service.js";

test("并发取同一个 id 只真取一次", async () => {
  resetCache(); resetCount();
  const [a, b] = await Promise.all([getUser(7), getUser(7)]);
  assert.deepEqual(a, b);
  assert.equal(loadCount(), 1, "并发同 id 也应当共用同一次 load");
});

test("并发取不同 id 各自真取", async () => {
  resetCache(); resetCount();
  await Promise.all([getUser("a"), getUser("b")]);
  assert.equal(loadCount(), 2, "不同 id 不应互相命中");
});

test("resetCache 会让并发中的后续调用重新取", async () => {
  resetCache(); resetCount();
  const p = getUser(9);
  resetCache();
  await p;
  await getUser(9);
  assert.equal(loadCount(), 2, "resetCache 之后重新取");
});

